import { getAssessmentDefinition, validateProvenance } from './definitions.js'

// Human-authored explanations of the registered constructs, not norms or new
// scoring rules. The scorer/definitions remain the sole calculation authority.
// Source trail: docs/assessments/2026-10-12-result-explanations.md.
export const RESULT_EXPLANATIONS_VERSION = '2026-10-12.v1'
const pair = (en, ru) => Object.freeze({ en, ru })
const meanings = {}
const add = (keys, en, ru) => {
  for (const key of keys.split('|')) meanings[key] = pair(en, ru)
}

// Original HH checks: interpret the actual items, not a guessed meaning of the
// title. In particular approval/perfectionism/energy-drains score resources.
add('resources.social_battery.overall', 'Your responses describe energy for company, asking for contact and taking space when tired. This combines social comfort and recovery; it does not measure popularity or how sociable you should be.', 'Ответы описывают силы для общения, возможность попросить контакта и взять паузу при усталости. Здесь сочетаются комфорт и восстановление; это не оценка популярности и не требование быть общительнее.')
add('function.focus_mode.overall', 'This check brings together choosing a priority, beginning a task, staying with it and finishing a small step. A lower score can help locate difficult working conditions; it does not establish an attention disorder.', 'Здесь объединены выбор приоритета, начало дела, удержание внимания и завершение небольшого шага. Меньший балл помогает заметить трудные условия работы, но не устанавливает расстройство внимания.')
add('state.stress_weather.overall', 'The answers describe how pressure appears in bodily tension, crowded thoughts, difficulty resting and contact with others. A larger score means more of these reported experiences, without identifying their cause.', 'Ответы описывают проявления нагрузки в телесном напряжении, перегруженных мыслях, трудностях отдыха и общении. Больший балл означает больше таких переживаний, но не определяет их причину.')
add('resources.recharge_decoder.overall', 'The score combines perceived recovery from sleep, pauses, quiet, movement and contact. It shows how available recovery feels overall; the total alone cannot identify which particular form of rest works best.', 'Балл объединяет ощущение восстановления после сна, пауз, тишины, движения и общения. Он показывает общую доступность восстановления; одна сумма не определяет, какой вид отдыха помогает лучше.')
add('resources.boundary_radar.overall', 'The responses concern noticing limits, expressing a preference, taking time to decide and respecting another person’s refusal. This is self-reflection about boundaries, not evidence that an interaction is safe or consensual.', 'Ответы касаются распознавания границ, выражения предпочтений, времени на решение и уважения чужого отказа. Это самонаблюдение о границах, а не подтверждение безопасности или согласия в конкретной ситуации.')
add('resources.tiny_joys.overall', 'This reflects noticing small pleasant moments, curiosity, relaxation and warmth during the week. It does not require constant happiness, and fewer such moments do not by themselves establish depression.', 'Показатель отражает небольшие приятные моменты, любопытство, расслабление и тепло за неделю. Постоянная радость не обязательна, а меньшее число таких моментов само по себе не устанавливает депрессию.')
add('resources.sleep_reset.overall', 'This combines how restorative and predictable sleep feels, winding down and habits that support rest. It describes your sleep experience and routines; it does not measure sleep stages or diagnose a sleep disorder.', 'Здесь сочетаются ощущение восстановления и предсказуемости сна, вечернее успокоение и привычки отдыха. Это описание опыта и режима сна; его стадии и нарушения этим тестом не диагностируются.')
add('state.morning_battery.overall', 'The responses concern energy after waking, mental clarity, bodily readiness and a manageable start to the day. They describe the morning experience rather than measuring a physical energy reserve.', 'Ответы касаются сил после пробуждения, ясности мысли, готовности тела и посильного начала дня. Это описание утреннего состояния, а не измерение физического запаса энергии.')
add('resources.evening_landing.overall', 'The score describes switching out of obligations, leaving unfinished tasks for tomorrow and reducing stimulation before sleep. More points mean these transitions felt more available, not that every evening needs a strict routine.', 'Балл описывает возможность завершить дела, отложить незавершённое до завтра и уменьшить стимуляцию перед сном. Больший балл означает большую доступность этих переходов, а не необходимость строгого вечернего режима.')
add('function.decision_fog.overall', 'This check concerns indecision, mental overload and difficulty making ordinary choices. A greater score indicates more reported decision difficulty; it does not measure intelligence or prove that your decisions are wrong.', 'Опросник касается нерешительности, умственной перегрузки и сложностей обычного выбора. Больший балл отражает больше таких трудностей, но не измеряет интеллект и не доказывает ошибочность решений.')
add('function.start_button.overall', 'The score describes practical access to starting: making a task smaller, finding a first action and beginning before everything feels ready. It is about the conditions for action, not a judgement of willpower.', 'Балл описывает доступность начала: уменьшить задачу, найти первое действие и приступить без полной готовности. Это условия для действия, а не оценка силы воли.')
add('state.screen_saturation.overall', 'The responses concern screen-related overload and difficulty disengaging from devices. The score can prompt a comparison of comfort before and after a break; it cannot establish that screens caused a health problem.', 'Ответы касаются перегрузки при использовании экранов и трудностей переключения с устройств. Можно сравнить самочувствие до и после паузы; балл не доказывает, что экран вызвал проблему со здоровьем.')
add('state.inner_critic.overall', 'This describes harsh self-evaluation, dwelling on mistakes and pressure from internal standards. More points indicate more reported self-critical pressure, not a measure of your worth or the accuracy of those criticisms.', 'Показатель описывает жёсткую самооценку, застревание на ошибках и давление внутренних требований. Больший балл означает больше самокритичного давления, а не оценку вашей ценности или справедливости критики.')
add('resources.inner_ally.overall', 'The responses describe access to a supportive and fair way of relating to yourself during difficulty. More support does not require ignoring mistakes; a smaller score is not evidence that you lack worth or ability.', 'Ответы описывают доступность поддерживающего и справедливого отношения к себе в трудностях. Поддержка не требует игнорировать ошибки; меньший балл не означает недостатка ценности или способностей.')
add('resources.meaning_compass.overall', 'This check concerns a sense of personal direction and connection between daily actions and what matters to you. It does not assign a correct purpose in life or judge which values you should hold.', 'Опросник касается личного направления и связи повседневных действий с важным для вас. Он не назначает правильный смысл жизни и не оценивает, каких ценностей следует придерживаться.')
add('resources.motivation_spark.overall', 'The score combines interest, a meaningful reason to act and a manageable next step. It describes current access to motivation, which can vary with fatigue and context; it is not a fixed trait of being motivated or lazy.', 'Балл объединяет интерес, значимый повод действовать и доступный следующий шаг. Мотивация может меняться с усталостью и обстоятельствами; это не постоянный ярлык мотивированности или лени.')
add('resources.change_readiness.overall', 'This reflects clarity about a desired change, willingness to experiment and support for a first step. Readiness is specific to the change you had in mind; more points do not mean you must act immediately.', 'Показатель отражает ясность желаемого изменения, готовность пробовать и поддержку первого шага. Готовность относится к задуманной перемене; больший балл не обязывает действовать немедленно.')
add('function.workload_weather.overall', 'Despite the title, higher scores mean more reported manageability: clearer priorities, enough time, realistic demands and room outside work. The score does not count workload or rate job performance.', 'Несмотря на название, больший балл означает большую управляемость: ясные приоритеты, время, посильные требования и место для жизни вне работы. Балл не измеряет объём работы или профессиональные результаты.')
add('state.body_signals.overall', 'This describes noticing tension and ordinary needs for food, water, movement or rest, and responding to them. More points indicate reported awareness, not greater illness or proof of a psychological cause.', 'Показатель описывает распознавание напряжения и обычных потребностей в еде, воде, движении или отдыхе и отклик на них. Больший балл означает больше осознанности, а не болезни или доказанную психологическую причину.')
add('resources.rest_permission.overall', 'The responses concern allowing a pause before exhaustion and resting without having to earn it. This is about your relationship with rest, not a claim that more inactivity is always better.', 'Ответы касаются возможности остановиться до истощения и отдыхать без необходимости заслужить паузу. Это отношение к отдыху, а не утверждение, что меньше активности всегда лучше.')
add('resources.closeness_compass.overall', 'This reflects recognizing needs for closeness and space, receiving care and keeping your own preferences. It does not determine an attachment type or judge the quality or future of a relationship.', 'Показатель отражает распознавание потребностей в близости и пространстве, принятие заботы и сохранение своих предпочтений. Он не определяет тип привязанности, качество или будущее отношений.')
add('resources.confidence_pulse.overall', 'The answers describe trust in handling ordinary problems, trying a step without certainty and recovering after mistakes. This is reported everyday confidence, not a test of competence or guaranteed success.', 'Ответы описывают доверие к себе в обычных задачах, попытку без гарантии и восстановление после ошибок. Это повседневная уверенность, а не проверка компетентности или гарантия успеха.')
add('resources.playfulness_pulse.overall', 'This reflects room for curiosity, humour, improvisation and enjoyment without a productivity requirement. A lower score may invite reflection on current demands; it does not mean you have the wrong personality.', 'Показатель отражает место для любопытства, юмора, импровизации и удовольствия без требования продуктивности. Меньший балл предлагает посмотреть на текущую нагрузку, а не говорит о неправильной личности.')
add('function.daily_rhythm.overall', 'The score brings together predictable sleep, meals, movement and transitions between activity and rest. It describes whether the day’s structure supports you, rather than prescribing one ideal timetable.', 'Балл объединяет предсказуемость сна, питания, движения и переходов между делами и отдыхом. Он описывает поддержку со стороны распорядка, а не предписывает идеальное расписание.')
add('state.money_pressure.overall', 'This combines reported financial worry with practical ways of handling uncertainty. It describes the experience of money-related pressure, not your income, debt, creditworthiness or the quality of a financial decision.', 'Показатель объединяет беспокойство о деньгах и практические способы обращения с неопределённостью. Это переживание финансового давления, а не оценка дохода, долгов, кредитоспособности или финансовых решений.')
add('state.overthinking_loop.overall', 'The responses describe repeated thinking that stops bringing new information and difficulty shifting attention away from uncertainty. The final item concerns relief from action or a pause; it is not reversed in this original version, so the combined score is not a pure measure of difficulty.', 'Ответы описывают повторное обдумывание без новой информации и трудности переключения с неопределённости. Последний пункт касается помощи от действия или паузы и в этой авторской версии не обращается, поэтому общий балл не является чистой мерой трудности.')
add('resources.felt_safety.overall', 'This describes recognizing bodily ease, choosing comfortable surroundings and having the option to pause or decline contact. A high score cannot establish that a person, place or interaction is objectively safe.', 'Показатель описывает распознавание телесного спокойствия, выбор комфортной среды и возможность остановиться или отказаться от контакта. Высокий балл не подтверждает объективную безопасность человека, места или взаимодействия.')
add('resources.emotion_clarity.overall', 'The responses concern telling feelings apart, naming them and allowing more than one feeling at a time. More points describe perceived emotional clarity, not an obligation to understand or control every emotion.', 'Ответы касаются различения и называния чувств и признания нескольких переживаний одновременно. Больший балл описывает субъективную ясность, а не обязанность понимать или контролировать каждую эмоцию.')
add('resources.loss_adjustment.overall', 'This reflects room for varied reactions after loss or change, available support and caring for daily needs. It does not place you in a stage of grief or set a deadline for feeling better.', 'Показатель отражает место для разных реакций после утраты или перемен, доступную поддержку и заботу о повседневных нуждах. Он не определяет стадию горя и не задаёт срок восстановления.')
add('resources.belonging.overall', 'The score concerns feeling welcome, being yourself and finding chosen contact without performing a role. It describes perceived belonging, not an objective count of friends or your social value.', 'Балл касается ощущения принятия, возможности быть собой и выбранного контакта без исполнения роли. Это переживание принадлежности, а не число друзей или социальная ценность.')
add('function.conflict_repair.overall', 'This reflects pausing, explaining a concern, listening and considering repair after everyday disagreement. The score does not require reconciliation or staying in a conversation that feels unsafe.', 'Показатель отражает паузу, объяснение затруднения, слушание и возможность восстановить диалог после обычного разногласия. Балл не обязывает мириться или оставаться в небезопасном разговоре.')
add('resources.family_roles.overall', 'The responses describe distinguishing your wishes from family expectations and choosing realistic responsibilities. They do not diagnose family members or establish who is to blame for a pattern.', 'Ответы описывают различение своих желаний и семейных ожиданий и выбор посильной ответственности. Они не диагностируют родственников и не определяют виновного в семейных отношениях.')
add('resources.inner_imagery.overall', 'This reflects comfort using images or metaphors to explore feelings and choices while remaining able to stop. It is not a test of spiritual ability, hidden memories or the truth of an imagined scene.', 'Показатель отражает комфорт в использовании образов и метафор для исследования чувств и выбора с возможностью остановиться. Это не проверка духовных способностей, скрытых воспоминаний или истинности воображаемой сцены.')
add('resources.values_direction.overall', 'The score describes identifying what matters to you and connecting it with small choices, including revising a goal. It does not rank values or equate productivity with living meaningfully.', 'Балл описывает распознавание важного для вас и связь с небольшими решениями, включая пересмотр цели. Он не ранжирует ценности и не приравнивает продуктивность к осмысленной жизни.')
add('resources.life_transition.overall', 'This reflects finding stable routines, support and manageable choices during a change. It describes available anchors, not whether you are adapting at the correct speed.', 'Показатель отражает устойчивые привычки, поддержку и посильный выбор в период перемен. Это доступные опоры, а не оценка правильной скорости адаптации.')
add('function.speaking_up.overall', 'The responses concern expressing a preference, asking a clear question, declining or requesting time. They describe perceived room to speak, which also depends on the relationship and situation.', 'Ответы касаются выражения предпочтений, ясных вопросов, отказа или просьбы о времени. Они описывают ощущаемую возможность высказаться, зависящую также от отношений и ситуации.')
add('function.sustainable_pace.overall', 'This describes adjusting demands to capacity, recognizing overload and protecting recovery. A greater score means more reported flexibility in pacing, not a higher amount of work you should take on.', 'Показатель описывает соотнесение нагрузки с силами, распознавание перегрузки и сохранение восстановления. Больший балл означает гибкость темпа, а не больший объём работы, который следует взять.')
add('resources.support_seeking.overall', 'The score concerns identifying when help would be useful, naming a specific request and receiving help with boundaries. It does not measure how deserving you are of support or oblige you to disclose private matters.', 'Балл касается распознавания потребности в помощи, конкретной просьбы и принятия поддержки с границами. Он не измеряет, насколько вы достойны помощи, и не обязывает раскрывать личное.')
add('state.sensory_comfort.overall', 'Higher scores describe noticing sensory needs and adjusting light, noise, movement or space. They do not indicate greater sensory sensitivity, a neurological condition or a need for exposure exercises.', 'Большие баллы описывают распознавание сенсорных потребностей и настройку света, шума, движения или пространства. Они не означают большую чувствительность, неврологическое состояние или необходимость упражнений на привыкание.')
add('function.goal_obstacles.overall', 'This reflects making a goal concrete, distinguishing real constraints from imagined outcomes and finding a workable first step. The score does not estimate the likelihood of success or remove external barriers.', 'Показатель отражает конкретность цели, различение реальных ограничений и предполагаемых исходов и поиск посильного шага. Балл не оценивает вероятность успеха и не отменяет внешние препятствия.')
add('state.body_mind_context.overall', 'Higher scores describe observing bodily sensations and their context while keeping sensation, worry and possible causes separate. They do not show that a symptom is psychological or replace medical assessment.', 'Большие баллы описывают наблюдение за ощущениями и контекстом с различением симптома, тревоги и возможной причины. Они не доказывают психологическое происхождение жалобы и не заменяют медицинскую оценку.')
add('resources.energy_drains.overall', 'Despite the name, higher scores indicate more awareness of energy demands and recovery options: recognizing tiring tasks, early pause signals and a lighter alternative. They do not mean more exhaustion.', 'Несмотря на название, больший балл означает лучшее распознавание затрат сил и способов восстановления: утомляющих дел, ранних сигналов паузы и более лёгкой альтернативы. Он не означает большее истощение.')
add('resources.social_ease.overall', 'This reflects feeling able to join a conversation, be curious, ask questions and choose a suitable amount of contact. It is about everyday social flexibility, not an anxiety diagnosis or a requirement to socialize.', 'Показатель отражает возможность вступить в разговор, проявить интерес, задать вопрос и выбрать объём контакта. Это гибкость в общении, а не диагностика тревоги или обязанность общаться.')
add('resources.solitude_choice.overall', 'The responses describe distinguishing wanted solitude from unwanted disconnection and being able to seek contact when desired. Neither more time alone nor more company is automatically the better outcome.', 'Ответы описывают различение желанного уединения и нежелательной разобщённости и возможность искать контакт по желанию. Ни больше одиночества, ни больше общения не является автоматически лучшим исходом.')
add('resources.relationship_balance.overall', 'This describes noticing mutuality, receiving care and supporting others without overlooking your own limits. The score represents your reflection, not a rating of another person or proof that a relationship is equal.', 'Показатель описывает замеченную взаимность, принятие заботы и поддержку других с учётом своих границ. Это ваше наблюдение, а не оценка другого человека или доказательство равноправия отношений.')
add('state.approval_pressure.overall', 'Higher scores mean more reported freedom to notice approval-seeking and keep your preferences, including reconsidering a yes. They do not mean more pressure to please, despite the questionnaire’s title.', 'Большие баллы означают больше свободы замечать поиск одобрения и сохранять свои предпочтения, включая пересмотр согласия. Несмотря на название теста, это не большее давление всем нравиться.')
add('function.perfectionism_pressure.overall', 'Higher scores indicate more flexibility around standards: beginning, accepting harmless mistakes, requesting feedback and stopping when enough is done. They do not mean more perfectionism or lower work quality.', 'Большие баллы означают большую гибкость требований: начать, допустить безвредную ошибку, попросить обратную связь и вовремя завершить. Они не означают больше перфекционизма или худшее качество работы.')
add('resources.uncertainty_flexibility.overall', 'This reflects taking a manageable step without a guarantee, separating answerable questions from unknowns and updating plans. It is not a request to ignore risks or make a major decision without information.', 'Показатель отражает посильный шаг без гарантии, различение решаемых вопросов и неизвестного и пересмотр планов. Это не призыв игнорировать риски или принимать важное решение без информации.')
add('resources.role_freedom.overall', 'The responses concern seeing yourself beyond duties, recognizing interests and choosing how to respond rather than following a role automatically. This is room for choice, not evidence that your existing roles are wrong.', 'Ответы касаются восприятия себя за пределами обязанностей, собственных интересов и выбора реакции вместо автоматического следования роли. Это пространство выбора, а не доказательство неправильности ваших ролей.')
add('function.work_boundaries.overall', 'This describes clarity about responsibilities, deadlines, availability and changing priorities at work or in study. More points indicate reported scope to negotiate these conditions, not an assessment of your employer.', 'Показатель описывает ясность ответственности, сроков, доступности и смены приоритетов в работе или учёбе. Больший балл означает ощущаемую возможность договариваться, а не оценку работодателя.')

// Separate dimensions remain separate: an overall average cannot tell us which
// answer, situation or life area produced it.
add('state.problem_intensity', 'Your rating describes how strong the main difficulty feels right now. It does not identify its cause or imply that all parts of life are equally affected.', 'Ваша оценка описывает силу основной трудности прямо сейчас. Она не определяет причину и не означает, что все сферы жизни затронуты одинаково.')
add('state.resource', 'This is your current sense of available energy and inner support. It can coexist with difficulty; resources and symptoms are not opposite ends of one health score.', 'Это ощущение доступных сил и внутренней опоры сейчас. Оно может сочетаться с трудностями: ресурсы и симптомы не являются противоположными концами одного балла здоровья.')
add('state.tension', 'The rating describes felt inner tension at this moment. It is a snapshot rather than a measure of a stable anxiety condition.', 'Оценка описывает ощущаемое внутреннее напряжение в данный момент. Это текущий срез, а не измерение постоянного тревожного состояния.')
add('state.fatigue', 'This is a rating of current tiredness or depletion. It does not separate sleep, physical health, workload and emotional contributors to fatigue.', 'Это оценка текущей усталости или истощения. Она не разделяет вклад сна, физического здоровья, нагрузки и эмоциональных факторов.')
add('state.life_impact', 'This describes how much the current difficulty interferes with everyday life. Interference is distinct from how intense the feeling itself is.', 'Показатель описывает, насколько текущая трудность мешает повседневной жизни. Помехи в делах отличаются от силы самого переживания.')
add('weekly.mood', 'This weekly rating describes emotional wellbeing across the period you considered. It can hide day-to-day variation and is not a depression screen.', 'Эта недельная оценка описывает эмоциональное самочувствие за выбранный период. Она может скрывать различия между днями и не является скринингом депрессии.')
add('weekly.tension', 'This rating describes anxiety and tension during the week. It does not tell us which situations triggered them or establish an anxiety disorder.', 'Оценка описывает тревогу и напряжение за неделю. Она не показывает конкретные пусковые ситуации и не устанавливает тревожное расстройство.')
add('weekly.load', 'This reflects how heavy demands felt over the week. Perceived load is not the same as the number of tasks or your ability to do them.', 'Показатель отражает ощущаемую тяжесть требований за неделю. Переживаемая нагрузка не равна числу задач или способности с ними справиться.')
add('weekly.recovery', 'This describes how restorative sleep and rest felt during the week. It does not measure sleep duration or physical recovery directly.', 'Показатель описывает ощущаемое восстановление от сна и отдыха за неделю. Он не измеряет напрямую длительность сна или физическое восстановление.')
add('weekly.energy|resource.energy', 'This rating concerns energy that feels available for ordinary activity. It does not measure fitness or establish a physical explanation for reduced energy.', 'Оценка касается сил, доступных для обычной активности. Она не измеряет физическую форму и не устанавливает телесную причину снижения энергии.')
add('weekly.clarity', 'This describes how clear and organized thinking felt during the week. It is self-observation, not a test of memory, intelligence or cognitive impairment.', 'Показатель описывает ощущение ясности и организованности мыслей за неделю. Это самонаблюдение, а не проверка памяти, интеллекта или когнитивных нарушений.')
add('weekly.connection|resource.connection', 'This describes felt connection with other people. It captures your experience of contact, rather than how many people you know or whether someone else cares.', 'Показатель описывает ощущение связи с другими. Это переживание контакта, а не число знакомых или доказательство чужого отношения к вам.')
add('weekly.functioning', 'This rating describes how manageable everyday activities felt during the week. It does not define your value by productivity or identify the cause of difficulty.', 'Оценка описывает доступность повседневных дел за неделю. Она не определяет вашу ценность через продуктивность и не выявляет причину трудностей.')
add('resource.self_support', 'This concerns your present sense of being able to support yourself through a difficulty. It is distinct from practical help available from other people.', 'Показатель касается текущего ощущения способности поддержать себя в трудности. Это отличается от практической помощи со стороны других людей.')
add('resource.support', 'This describes how available outside help feels when you need it. A lower rating can reflect circumstances and access, not a failure to be resilient.', 'Показатель описывает ощущаемую доступность внешней помощи при необходимости. Меньшая оценка может отражать обстоятельства и доступность, а не недостаток устойчивости.')
add('resource.agency', 'This rating concerns having a choice or a workable next action. It does not imply that you control other people or circumstances outside your influence.', 'Оценка касается наличия выбора или посильного следующего действия. Она не означает контроля над другими людьми и внешними обстоятельствами.')
add('resource.meaning', 'This describes a current sense of purpose or direction. It does not rank your life’s meaning against other people’s or require a fixed long-term goal.', 'Показатель описывает текущее ощущение смысла или направления. Он не сравнивает значимость вашей жизни с чужой и не требует неизменной долгосрочной цели.')
add('resources.overall', 'This combines energy, inner support, outside help, connection, agency and meaning. Different resource profiles can have the same overall score; read the individual dimensions before choosing a next step.', 'Здесь объединены энергия, внутренняя опора, внешняя помощь, связь, возможность действовать и смысл. Разные сочетания ресурсов могут дать один общий балл; перед выбором шага рассмотрите отдельные шкалы.')
add('resources.monthly.self', 'This monthly dimension concerns the relationship with yourself and your needs. It is a reflection on the past month, not a permanent personality judgement.', 'Эта месячная шкала касается отношения к себе и своим потребностям. Это наблюдение за месяц, а не постоянная оценка личности.')
add('resources.monthly.relationships', 'This describes how relationships and connection felt over the month. It does not diagnose a relationship or establish another person’s intentions.', 'Показатель описывает переживание отношений и контакта за месяц. Он не диагностирует отношения и не устанавливает намерения другого человека.')
add('resources.monthly.body', 'This monthly dimension concerns bodily wellbeing and recovery as you experienced them. It does not determine the medical cause of discomfort or fatigue.', 'Эта месячная шкала касается ощущаемого телесного благополучия и восстановления. Она не определяет медицинскую причину дискомфорта или усталости.')
add('resources.monthly.work', 'This reflects how work or purposeful activity fitted your capacity during the month. It is not an external assessment of performance or an instruction to do more.', 'Показатель отражает соответствие работы или значимой деятельности вашим возможностям за месяц. Это не внешняя оценка результатов и не требование делать больше.')
add('resources.monthly.meaning', 'This describes the month’s sense of direction and connection to what matters. A change may reflect changing priorities rather than a loss of personal worth.', 'Показатель описывает ощущение направления и связи с важным за месяц. Изменение может отражать смену приоритетов, а не потерю личной ценности.')
add('resources.monthly.support', 'This reflects perceived practical and emotional help during the month. Availability can depend on people, services and circumstances as well as on asking.', 'Показатель отражает ощущаемую практическую и эмоциональную помощь за месяц. Доступность зависит от людей, служб и обстоятельств, а не только от умения попросить.')
add('resources.monthly.overall', 'This is a combined view of the six monthly life areas, not a total health score. The same average can conceal a supported area alongside one that needs attention.', 'Это сводный взгляд на шесть жизненных сфер за месяц, а не общий балл здоровья. Одинаковое среднее может скрывать сочетание благополучной сферы и той, которой нужно внимание.')

add('resources.love_affection.expressing', 'This reflects expressing appreciation and care in a way that respects another person’s space. It does not measure how much you love someone.', 'Показатель отражает выражение признательности и заботы с уважением к чужому пространству. Он не измеряет силу любви к человеку.')
add('resources.love_affection.receiving', 'This reflects recognizing care, accepting it without debt and naming comfortable forms of affection. It does not oblige you to welcome any particular gesture.', 'Показатель отражает распознавание заботы, принятие без долга и выбор комфортной нежности. Он не обязывает принимать конкретный жест.')
add('resources.trust_dialogue.honesty', 'This concerns explaining needs, asking for clarity and expressing disagreement. It reflects your communication experience, not proof of another person’s honesty.', 'Шкала касается объяснения потребностей, просьб о ясности и выражения несогласия. Это ваш опыт общения, а не доказательство чужой честности.')
add('resources.trust_dialogue.discernment', 'This concerns noticing consistency between promises and actions and allowing trust to develop gradually. It cannot certify that another person is trustworthy.', 'Шкала касается согласованности слов и действий и постепенного формирования доверия. Она не удостоверяет надёжность другого человека.')
add('resources.emotional_intimacy.opening', 'This reflects sharing a feeling or asking for emotional support at a depth you choose. Openness does not require disclosure of every private detail.', 'Показатель отражает выражение чувства или просьбу об эмоциональной поддержке на выбранной вами глубине. Открытость не требует раскрывать всё личное.')
add('resources.emotional_intimacy.pacing', 'This reflects recognizing a need for distance and respecting how much each person wants to share. A slower pace is a legitimate choice rather than a deficit.', 'Показатель отражает распознавание потребности в дистанции и уважение к объёму откровенности каждого. Медленный темп является допустимым выбором, а не недостатком.')
add('resources.intimacy_consent.agency', 'This reflects awareness of the right to refuse, pause or change your mind about intimacy. A questionnaire response never establishes consent to a real interaction.', 'Показатель отражает понимание права отказать, остановиться или передумать о близости. Ответ в анкете никогда не устанавливает согласие на реальное взаимодействие.')
add('resources.intimacy_consent.mutuality', 'This concerns asking whether closeness is welcome and respecting hesitation or a changed mind. Consent must still be freely expressed in the actual situation.', 'Шкала касается уточнения желанности близости и уважения к сомнению или изменению решения. В конкретной ситуации согласие всё равно должно быть свободным.')
add('resources.desire_dialogue.awareness', 'This reflects noticing your own preferences, including neutral, low or absent desire, separately from expectations. Higher scores do not mean more desire or better sexual health.', 'Показатель отражает распознавание собственных предпочтений, включая нейтральное, слабое или отсутствующее желание, отдельно от ожиданий. Больший балл не означает больше желания или лучшее сексуальное здоровье.')
add('resources.desire_dialogue.dialogue', 'This concerns discussing comfort, boundaries and different preferences without performance pressure. It does not assume a partner or a duty to pursue intimacy.', 'Шкала касается разговора о комфорте, границах и различиях предпочтений без требования результата. Наличие партнёра и обязанность стремиться к близости не предполагаются.')
add('resources.sexual_self_kindness.kindness', 'This reflects relating patiently to sexual feelings and uncertainty without comparison or shame. It does not categorize identity, orientation or preferences.', 'Показатель отражает терпеливое отношение к сексуальным чувствам и неопределённости без сравнения и стыда. Он не классифицирует идентичность, ориентацию или предпочтения.')
add('resources.sexual_self_kindness.choice', 'This concerns choosing privacy and whether to pursue intimacy independently of pressure. Choosing no sexual activity is compatible with autonomy.', 'Шкала касается выбора приватности и близости независимо от давления. Отказ от сексуальной активности совместим с самостоятельностью.')
add('resources.tantra_presence.grounding', 'This reflects voluntary awareness of breath, posture and present sensations without forcing change. It does not measure spiritual attainment or prescribe breathwork.', 'Показатель отражает добровольное внимание к дыханию, позе и ощущениям без принуждения к изменению. Он не измеряет духовные достижения и не назначает дыхательные практики.')
add('resources.tantra_presence.choice', 'This reflects staying aware of your needs and being able to slow down or leave a practice. Presence does not create an obligation to touch or be touched.', 'Показатель отражает внимание к своим потребностям и возможность замедлить или прекратить практику. Присутствие не создаёт обязанности касаться или принимать прикосновения.')
add('resources.sensual_joy.senses', 'This concerns noticing ordinary pleasant sensations and adjusting stimulation when it is too much. It does not require intense experiences or sexual contact.', 'Шкала касается обычных приятных ощущений и уменьшения чрезмерной стимуляции. Интенсивные переживания и сексуальный контакт не требуются.')
add('resources.sensual_joy.playfulness', 'This concerns allowing enjoyment and playfulness without earning permission or approval. It can apply equally to chosen solitude or connection.', 'Шкала касается разрешения себе удовольствия и игры без необходимости заслужить одобрение. Она одинаково применима к выбранному уединению и контакту.')

// Published instrument constructs. These are paraphrases tied to the original
// form below; optional HH actions are labelled separately in the renderer.
add('symptoms.cbi_personal.total', 'The authors define personal burnout as prolonged physical and psychological exhaustion. The six questions cover tiredness, physical and emotional exhaustion, feeling unable to continue, feeling worn out and weakness. This subscale asks about exhaustion in general, regardless of whether you work; it does not establish that work caused it.', 'Авторы определяют личное выгорание как продолжительное физическое и психологическое истощение. Шесть вопросов охватывают усталость, физическое и эмоциональное истощение, ощущение невозможности продолжать, измотанность и слабость. Эта шкала касается истощения в целом, независимо от работы; она не устанавливает, что причиной была работа.')
add('symptoms.cbi_work.total', 'The work-related CBI asks about physical and psychological exhaustion that you perceive as connected with work. Its seven questions cover emotional exhaustion, frustration, fatigue before or after work and energy left for private life. The attribution is your reported perception, not proof of a workplace cause.', 'Рабочая шкала CBI касается физического и психологического истощения, которое вы связываете с работой. Семь вопросов охватывают эмоциональное истощение, фрустрацию, усталость до или после работы и силы на личную жизнь. Связь с работой является вашим восприятием, а не доказанной причиной.')
add('symptoms.cbi_client.total', 'The client-related CBI concerns exhaustion you associate with working with clients, patients or other service recipients. Its six questions cover difficulty, frustration, energy cost, imbalance in giving and receiving and doubts about continuing this work. It does not rate individual clients or general social ability.', 'Клиентская шкала CBI касается истощения, которое вы связываете с работой с клиентами, пациентами или получателями помощи. Шесть вопросов охватывают трудность, фрустрацию, затраты сил, дисбаланс отдачи и получения и сомнения о продолжении работы. Она не оценивает конкретных клиентов или общую общительность.')
add('symptoms.phq2.total|symptoms.phq4.depression', 'These two items ask how often low mood and reduced interest or pleasure occurred over the past two weeks. Together they provide a brief depression-screening signal; they do not cover every depressive symptom or establish a diagnosis.', 'Два пункта спрашивают о частоте сниженного настроения и уменьшения интереса или удовольствия за последние две недели. Вместе они дают краткий скрининговый сигнал; все симптомы депрессии не охватываются и диагноз не устанавливается.')
add('symptoms.gad2.total|symptoms.phq4.anxiety', 'These two items concern nervousness and difficulty stopping or controlling worry during the past two weeks. They screen for anxiety experiences, without determining the cause or a particular anxiety diagnosis.', 'Два пункта касаются нервозности и трудностей остановки или контроля беспокойства за последние две недели. Это скрининг тревожных переживаний без определения причины или конкретного диагноза.')
add('symptoms.phq4.total', 'The PHQ-4 combines the two mood items and two anxiety items from the past two weeks. The total describes combined symptom burden; the separate subscales are needed to see whether mood, worry or both contributed.', 'PHQ-4 объединяет два пункта настроения и два пункта тревоги за последние две недели. Сумма описывает общую выраженность симптомов; вклад настроения и беспокойства нужно рассматривать по отдельным подшкалам.')
add('symptoms.phq9.total', 'The PHQ-9 sums the reported frequency of nine depressive symptoms over two weeks, including mood, interest, sleep, energy, appetite, self-evaluation, concentration, movement and thoughts of death or self-harm. The total is not a safety assessment: the safety item must be considered separately, even when the total is small.', 'PHQ-9 суммирует частоту девяти депрессивных симптомов за две недели: настроение, интерес, сон, силы, аппетит, отношение к себе, концентрацию, движения и мысли о смерти или самоповреждении. Сумма не является оценкой безопасности: соответствующий пункт рассматривается отдельно даже при небольшом итоге.')
add('symptoms.phq_8.total', 'The PHQ-8 sums the frequency of eight depressive symptoms over the past two weeks. Unlike the PHQ-9 it does not include the death/self-harm item; no safety conclusion can be drawn from a low or high total.', 'PHQ-8 суммирует частоту восьми депрессивных симптомов за последние две недели. В отличие от PHQ-9 здесь нет пункта о смерти или самоповреждении; ни низкий, ни высокий итог не позволяет сделать вывод о безопасности.')
add('symptoms.gad7.total', 'The seven GAD-7 items ask about recent nervousness, worry, difficulty relaxing, restlessness, irritability and fear over two weeks. A higher sum reflects more frequent reported anxiety symptoms, not confirmation of generalized anxiety disorder.', 'Семь пунктов GAD-7 касаются нервозности, беспокойства, трудностей расслабления, неусидчивости, раздражительности и страха за две недели. Большая сумма означает более частые тревожные симптомы, а не подтверждение генерализованного тревожного расстройства.')
add('symptoms.k6.total', 'K6 asks about the frequency of six forms of nonspecific psychological distress over the past 30 days. It brings together nervousness, hopelessness, restlessness, depressed feelings, effort and worthlessness; it cannot identify which disorder, if any, accounts for distress.', 'K6 спрашивает о частоте шести проявлений неспецифического психологического дистресса за 30 дней: нервозности, безнадёжности, неусидчивости, подавленности, усилия и чувства никчёмности. Шкала не определяет, связано ли напряжение с конкретным расстройством.')
add('symptoms.k10.total', 'K10 is the ten-item measure of nonspecific psychological distress over the past 30 days, covering anxiety-like and depressive experiences. This implementation sums 0–4 answers to 0–40; categories from a 10–50 scoring convention must not be applied to this total.', 'K10 измеряет неспецифический психологический дистресс по десяти пунктам за 30 дней, охватывая тревожные и депрессивные переживания. Здесь ответы 0–4 суммируются в 0–40; категории из схемы 10–50 нельзя переносить на эту сумму.')
add('symptoms.phq15.total', 'PHQ-15 records how much a range of bodily symptoms bothered you over the past four weeks. The sum measures reported symptom burden, not whether symptoms are medically unexplained or caused by stress.', 'PHQ-15 отражает, насколько разные телесные симптомы беспокоили за последние четыре недели. Сумма описывает нагрузку симптомов, но не устанавливает, являются ли они медицински необъяснимыми или вызванными стрессом.')
add('resources.brcs.total', 'BRCS asks about adapting creatively to difficulty, influencing your responses and seeking ways to cope. The four-item total describes reported resilient coping rather than absence of distress or an unchangeable strength of character.', 'BRCS касается творческой адаптации к трудностям, влияния на свои реакции и поиска способов справляться. Сумма четырёх пунктов описывает заявленное совладание, а не отсутствие напряжения или неизменную силу характера.')
add('resources.rses_10.total', 'The Rosenberg scale describes overall positive and negative evaluation of yourself. Positively and negatively phrased statements are combined after reversal; the score is self-reported global self-esteem, not an objective measure of worth.', 'Шкала Розенберга описывает общее положительное и отрицательное отношение к себе. Разнонаправленные утверждения объединяются после обратного кодирования; результат отражает общую самооценку, а не объективную ценность человека.')
add('symptoms.ces_d_20.total', 'The CES-D asks about the frequency of depressive experiences during the past week, including mood, bodily/activation difficulties, interpersonal experiences and positive affect. Positively worded items are reversed; the sum does not establish a depressive disorder.', 'CES-D спрашивает о частоте депрессивных переживаний за последнюю неделю: настроении, телесных и деятельностных трудностях, межличностном опыте и положительных чувствах. Позитивные пункты кодируются обратно; сумма не устанавливает депрессивное расстройство.')
add('resources.erq.reappraisal', 'Cognitive reappraisal means changing how you understand a situation in order to alter its emotional impact. The six-item mean reflects reported habitual use of this strategy, not how successfully it worked in any particular event.', 'Когнитивная переоценка означает изменение понимания ситуации для изменения её эмоционального воздействия. Среднее шести пунктов отражает привычное использование стратегии, а не её успешность в конкретном событии.')
add('resources.erq.suppression', 'Expressive suppression means holding back the outward display of an emotion once it is present. The four-item mean describes reported use, not absence of feelings; whether restraint is useful depends on the situation.', 'Подавление экспрессии означает сдерживание внешнего выражения уже возникшей эмоции. Среднее четырёх пунктов описывает использование стратегии, а не отсутствие чувств; полезность сдерживания зависит от ситуации.')
add('resources.mspss.significant_other', 'These four MSPSS items describe perceived emotional help, comfort and sharing with a special person. The person need not be a romantic partner, and perceived support is different from support independently observed.', 'Эти четыре пункта MSPSS описывают ощущаемую эмоциональную помощь, утешение и возможность делиться с особым близким человеком. Это не обязательно романтический партнёр; ощущаемая поддержка отличается от независимо наблюдаемой.')
add('resources.mspss.family', 'These four items describe how available family help, emotional support and discussion of problems feel to you. They reflect perceived family support rather than a judgement about the family’s intentions.', 'Четыре пункта описывают ощущаемую доступность семейной помощи, эмоциональной поддержки и обсуждения проблем. Это восприятие поддержки семьи, а не оценка её намерений.')
add('resources.mspss.friends', 'These four items describe feeling able to count on friends and share both difficulties and enjoyable experiences. The score does not measure the number of friends or frequency of social contact.', 'Четыре пункта описывают возможность рассчитывать на друзей и разделять трудности и радостные события. Балл не измеряет число друзей или частоту общения.')
add('resources.mspss.overall', 'The overall MSPSS mean combines perceived support from family, friends and a special person. A similar total can result from very different support networks; compare its three subscales before drawing practical conclusions.', 'Общее среднее MSPSS объединяет ощущаемую поддержку семьи, друзей и особого близкого человека. Одинаковый итог возможен при очень разных источниках поддержки; перед практическим выводом сравните три подшкалы.')
add('function.hrqol4.general_health', 'This is the single overall self-rating of health, from excellent to poor. The numbers code ordered answer categories; a one-point difference is not a measured equal change in health.', 'Это один общий ответ о здоровье от отличного до плохого. Числа кодируют упорядоченные категории; разница в один балл не является измеренным равным изменением здоровья.')
add('symptoms.hrqol4.physically_unhealthy_days', 'This is the reported number of the past 30 days when physical health was not good. It counts days, not symptoms or diagnoses; the same day may also have been mentally difficult.', 'Это число дней за последние 30, когда физическое здоровье оценивалось как неблагополучное. Считаются дни, а не симптомы или диагнозы; тот же день мог быть психологически трудным.')
add('symptoms.hrqol4.mentally_unhealthy_days', 'This is the reported number of the past 30 days when mental health was not good, including stress or emotional problems. It is a day count rather than a diagnosis or a count of separate episodes.', 'Это число дней за последние 30 с психологическим неблагополучием, включая стресс или эмоциональные трудности. Это дни, а не диагноз или число отдельных эпизодов.')
add('function.hrqol4.activity_limitation_days', 'This counts days in the past 30 when poor physical or mental health kept you from usual activities. It describes interference with activity separately from the number of unhealthy days.', 'Это число дней за последние 30, когда физическое или психологическое неблагополучие мешало обычным занятиям. Ограничение деятельности рассматривается отдельно от числа неблагополучных дней.')
add('symptoms.hrqol4.unhealthy_days_index', 'CDC’s index adds physically and mentally unhealthy days and caps the result at 30. Because the two reports can overlap, this is a summary index rather than an exact calendar reconstruction of distinct unhealthy days.', 'Индекс CDC складывает физически и психологически неблагополучные дни и ограничивает итог 30. Поскольку ответы могут перекрываться, это сводный индекс, а не точное восстановление календаря отдельных дней.')
add('resources.hrqol4.healthy_days_index', 'This estimate is 30 minus the capped unhealthy-days index. It is derived from two reported day counts, not a separate answer or proof that every remaining day was free of all symptoms.', 'Эта оценка равна 30 минус ограниченный индекс неблагополучных дней. Она вычислена из двух ответов и не является отдельным ответом или доказательством отсутствия любых симптомов в остальные дни.')
add('symptoms.cdc_healthy_days.pain_days', 'This counts days over the past 30 when pain made usual activities difficult. It describes activity affected by pain, not pain intensity, location or medical cause.', 'Это число дней за последние 30, когда боль затрудняла обычные занятия. Описывается влияние боли на дела, а не её сила, место или медицинская причина.')
add('symptoms.cdc_healthy_days.sad_days', 'This is the number of the past 30 days with sadness, low mood or depressed feelings as asked in the item. It does not describe how long symptoms lasted within a day or establish depression.', 'Это число дней за последние 30 с грустью или подавленностью согласно вопросу. Оно не показывает длительность переживания внутри дня и не устанавливает депрессию.')
add('symptoms.cdc_healthy_days.anxiety_days', 'This counts days during the past 30 when worry, tension or anxiety was experienced. Frequency across days is distinct from the intensity of anxiety on any one day.', 'Это число дней за последние 30 с беспокойством, напряжением или тревогой. Частота по дням отличается от интенсивности тревоги в конкретный день.')
add('symptoms.cdc_healthy_days.sleep_days', 'This counts days over the past 30 when you felt you did not get enough rest or sleep. It records perceived insufficient recovery, not measured hours or a sleep-disorder diagnosis.', 'Это число дней за последние 30 с ощущением недостатка сна или отдыха. Оно отражает субъективный недостаток восстановления, а не измеренные часы или диагноз нарушения сна.')
add('resources.cdc_healthy_days.vitality_days', 'This counts the past 30 days when you felt very healthy and full of energy. It is a positive day count, not the reverse of every other symptom count.', 'Это число дней за последние 30 с ощущением хорошего здоровья и полноты сил. Это положительный показатель дней, а не обратное значение всех остальных симптомов.')
add('trait.extraversion|trait.ipip50.extraversion|trait.tipi.extraversion', 'Extraversion describes the reported tendency toward social engagement, talkativeness and outward energy. A quieter style and an outgoing style can each fit different situations; this is not a social-skills grade.', 'Экстраверсия описывает склонность к социальному участию, разговорчивости и внешней активности. Спокойный и общительный стили подходят разным ситуациям; это не оценка навыков общения.')
add('trait.agreeableness|trait.ipip50.agreeableness|trait.tipi.agreeableness', 'Agreeableness concerns reported consideration for others, cooperation and a sympathetic rather than antagonistic style. It does not measure moral worth or require agreement with everyone.', 'Доброжелательность касается внимания к другим, сотрудничества и сочувственного, а не конфликтного стиля. Она не измеряет нравственную ценность и не требует соглашаться со всеми.')
add('trait.conscientiousness|trait.ipip50.conscientiousness|trait.tipi.conscientiousness', 'Conscientiousness describes reported organization, dependability and follow-through. The score is not a test of ability; useful structure and flexibility depend on the task and circumstances.', 'Добросовестность описывает организованность, надёжность и доведение дел до конца. Балл не проверяет способности; полезность порядка и гибкости зависит от задачи и обстоятельств.')
add('trait.neuroticism', 'Mini-IPIP scores this factor toward emotional reactivity: greater endorsement of upset and mood fluctuation after reversing calmer responses. Its direction is opposite to the Emotional Stability factor in IPIP-50; do not compare their raw totals as if they pointed the same way.', 'Mini-IPIP направляет эту шкалу к эмоциональной реактивности: больше выражены расстройство и колебания настроения после реверса спокойных ответов. Направление противоположно эмоциональной устойчивости IPIP-50; их сырые суммы нельзя сравнивать как однонаправленные.')
add('trait.ipip50.emotional_stability|trait.tipi.emotional_stability', 'Emotional stability describes reported calmness and lower emotional reactivity after the keyed reversals. It is a broad personality description, not a screen for anxiety or a guarantee of psychological health.', 'Эмоциональная устойчивость описывает спокойствие и меньшую реактивность после предусмотренного реверса. Это широкое описание личности, а не скрининг тревоги или гарантия психологического здоровья.')
add('trait.intellect_imagination|trait.ipip50.intellect_imagination', 'Intellect/imagination concerns interest in ideas, abstraction and imaginative activity. It is a self-description of interests and tendencies, not a measured IQ or an assessment of intellectual capacity.', 'Интеллектуальные интересы и воображение касаются идей, абстракций и образной активности. Это самоописание интересов и склонностей, а не измеренный IQ или оценка умственных возможностей.')
add('trait.tipi.openness', 'Openness to experience describes reported interest in novelty and complexity rather than a preference for familiar, conventional approaches. Two broad items cannot give a detailed account of creativity, values or intelligence.', 'Открытость опыту описывает интерес к новизне и сложности в сравнении с предпочтением привычных подходов. Два широких пункта не дают подробной оценки творчества, ценностей или интеллекта.')
add('trait.bfas.volatility', 'Volatility concerns becoming angry, agitated or emotionally unsettled and losing composure. The score describes a self-reported personality tendency rather than a diagnosis or a prediction of aggressive behaviour.', 'Изменчивость касается раздражения, возбуждения, эмоциональной неустойчивости и потери самообладания. Балл описывает заявленную личностную склонность, а не диагноз или прогноз агрессивного поведения.')
add('trait.bfas.withdrawal', 'Withdrawal concerns worry, threat sensitivity, discouragement and self-conscious distress. Here it is an aspect of emotional reactivity, not simply a preference for solitude and not a depression diagnosis.', 'Уход от трудностей касается беспокойства, чувствительности к угрозам, упадка духа и переживания неловкости. Здесь это аспект эмоциональной реактивности, а не просто предпочтение уединения и не диагноз депрессии.')
add('trait.bfas.compassion', 'This personality aspect concerns interest in other people’s feelings and needs. It describes interpersonal sensitivity rather than self-compassion, and it does not measure a person’s moral worth.', 'Этот личностный аспект касается интереса к чувствам и потребностям других. Он описывает межличностную чуткость, а не самосострадание, и не измеряет нравственную ценность.')
add('trait.bfas.industriousness', 'Industriousness concerns starting, sustaining and completing goal-directed activity. This self-rating is distinct from intelligence, actual productivity or the barriers present in your environment.', 'Трудолюбие касается начала, поддержания и завершения целенаправленной деятельности. Самооценка отличается от интеллекта, фактической продуктивности и внешних препятствий.')
add('trait.bfas.orderliness', 'Orderliness concerns preferences for organization, routines, details and tidiness. A high or low preference can have different uses across contexts; it does not establish an obsessive-compulsive condition.', 'Упорядоченность касается предпочтения организации, режима, деталей и порядка. Большая и меньшая выраженность полезны в разных условиях; обсессивно-компульсивное состояние этим не устанавливается.')
add('trait.bfas.intellect', 'This aspect concerns engagement with complex ideas and your perceived ease of understanding or explaining them. It is not an ability test and cannot be converted into an IQ estimate.', 'Аспект касается вовлечённости в сложные идеи и субъективной лёгкости их понимания и объяснения. Это не тест способностей; результат нельзя переводить в оценку IQ.')
add('trait.bfas.openness', 'This aspect concerns aesthetic involvement, imagination and absorption in art, music or natural beauty. It is distinct from the Intellect aspect and does not grade artistic talent.', 'Аспект касается эстетической вовлечённости, воображения и погружения в искусство, музыку или красоту природы. Он отличается от интеллектуальных интересов и не оценивает художественный талант.')
add('trait.via.capacity_for_love', 'This brief scale concerns expressing, receiving and sharing close affection. It does not determine whether you are lovable or whether another person loves you.', 'Краткая шкала касается выражения, принятия и разделения близкой привязанности. Она не определяет, достойны ли вы любви и любит ли вас другой человек.')
add('trait.via.curiosity', 'Curiosity here concerns finding interest in activities and the surrounding world. It describes a tendency to engage with possibilities, not a measure of learning ability.', 'Любознательность здесь касается интереса к занятиям и окружающему миру. Это склонность исследовать возможности, а не измерение обучаемости.')
add('trait.via.forgiveness', 'This scale concerns letting go of grudges and allowing a fresh start. A score never requires excusing harm, removing boundaries or restoring contact with someone.', 'Шкала касается отпускания обиды и возможности нового начала. Балл не обязывает оправдывать вред, отменять границы или возобновлять контакт.')
add('trait.via.gratitude', 'The items concern recognizing and expressing appreciation for people and aspects of life. Gratitude can coexist with justified dissatisfaction; a score does not invalidate difficult experiences.', 'Пункты касаются признания и выражения благодарности людям и важному в жизни. Благодарность совместима с обоснованным недовольством; балл не обесценивает трудный опыт.')
add('trait.via.hope', 'This describes expectations and the ability to see possibilities despite difficulty. Hope is not a forecast, and a greater score does not guarantee a positive outcome.', 'Показатель описывает ожидания и возможность видеть перспективы в трудностях. Надежда не является прогнозом; больший балл не гарантирует хороший исход.')
add('trait.via.humor', 'This concerns using and retaining humour and playfulness in everyday life. It describes one style of relating, not a requirement to be entertaining or cheerful under pressure.', 'Шкала касается юмора и игривости в повседневной жизни. Это один стиль взаимодействия, а не обязанность развлекать других или быть весёлым под давлением.')
add('trait.via.perseverance', 'This concerns continuing a task despite obstacles and finishing what you start. Persistence is not always the right choice; the score does not judge when stopping or changing direction is appropriate.', 'Шкала касается продолжения дела при препятствиях и завершения начатого. Упорство не всегда лучший выбор; балл не решает, когда уместнее остановиться или сменить направление.')
add('trait.via.creativity', 'This concerns generating original approaches and doing things in new ways. It is a short self-description, not a performance test of artistic or scientific creativity.', 'Шкала касается новых подходов и оригинальных способов действия. Это краткое самоописание, а не проверка художественной или научной креативности.')
add('trait.via.social_intelligence', 'This concerns perceived awareness of feelings and social situations. It does not establish that an interpretation of another person’s thoughts or intentions is accurate.', 'Шкала касается ощущаемого понимания чувств и социальных ситуаций. Она не подтверждает точность прочтения чужих мыслей или намерений.')
add('trait.via.zest', 'This reflects reported vitality and enthusiasm for engaging with life. It describes a broad tendency, not a direct measurement of physical energy or an explanation of fatigue.', 'Показатель отражает заявленную живость и энтузиазм участия в жизни. Это широкая склонность, а не прямое измерение физических сил или объяснение усталости.')

export const DIMENSION_MEANINGS = Object.freeze(meanings)
const CBI_SOURCE = 'https://nfa.dk/media/a4wheblj/cbi-scales.pdf'
const SOURCE_REVIEW = Object.freeze({
  cbi: { status: 'original-guidance', url: CBI_SOURCE, reviewed: '2026-10-12', scope: 'Original NFA form: constructs, item counts, anchors, mean, work reversal and missingness; no clinical severity thresholds.' },
  phq: { status: 'original-guidance', url: 'https://case.edu/medicine/wellness-pathway/sites/default/files/2018-05/instructions.pdf', reviewed: '2026-10-12', scope: 'Spitzer/Williams/Kroenke author manual hosted by Case Western: pages 2–3 and 5–8, constructs, coding, variants and limits. No treatment algorithm implemented.' },
  kessler: { status: 'original-guidance', url: 'https://rckessler.scholars.harvard.edu/sites/g/files/omnuum8166/files/2026-03/Scoring_K6_K10.pdf', reviewed: '2026-10-12', scope: 'Author site and scoring sheet; nonspecific distress, coding 0–4, sums 0–24/0–40. Not a subtype diagnosis.' },
  ipip: { status: 'original-form', reviewed: '2026-10-12', scope: 'Official IPIP construct headings, item content and keying. Plain-language summaries are HH paraphrases; no norms or percentile conversion.' },
  tipi: { status: 'original-guidance', url: 'https://gosling.psy.utexas.edu/scales-weve-developed/ten-item-personality-measure-tipi/', reviewed: '2026-10-12', scope: 'Author guidance: two-item means with reversal; especially brief form with reduced precision.' },
  erq: { status: 'research-source', reviewed: '2026-10-12', scope: 'CMU Common Cold Project primary research measure documentation: purpose, anchors, 6/4 item means.' },
  cdc: { status: 'original-form', reviewed: '2026-10-12', scope: 'CDC original HRQOL-14 modules; exact day-count constructs and self-rated health categories. Derived indexes follow the unchanged registered scorer.' },
  rses: { status: 'original-guidance', reviewed: '2026-10-12', scope: 'Rosenberg custodian UMD guidance: ten-item global self-esteem, reversal, 0–30 scoring; population-specific norms required.' },
  mspss: { status: 'original-guidance', url: 'https://12fab08f-d2d3-ce70-6d1a-9d3fa0d8a67b.filesusr.com/ugd/5119f9_2f88fadcd382463daf5821e8af94a865.pdf#page=2', reviewed: '2026-10-12', scope: 'Zimet author site and linked two-page form: construct, 12 items, four each for family/friends/significant other, item membership, means and lack of established population norms.' },
  brcs: { status: 'original-publication-abstract', reviewed: '2026-10-12', scope: 'Sinclair and Wallston 2004 abstract: adaptive coping, four items, rheumatoid arthritis validation samples. Detailed scoring comes from registered definition; full original text not reviewed here.' },
  cesd: { status: 'original-publication-abstract', url: 'https://journals.sagepub.com/doi/abs/10.1177/014662167700100306', reviewed: '2026-10-12', scope: 'Radloff 1977 abstract: depressive symptoms in the general population. The registered 20-item form supplies past-week wording and reversal; full original manual not newly reviewed here.' },
})
export function resultExplanationSource(key) {
  if (key.startsWith('hh-')) return { status: 'original-hh-definition', reviewed: '2026-10-12', scope: 'Current registered HH questions and scoring; authored reflection, no independent norms.' }
  if (key.startsWith('cbi-')) return SOURCE_REVIEW.cbi
  if (/^(phq-|gad-)/.test(key)) return SOURCE_REVIEW.phq
  if (key === 'k6' || key === 'k10') return SOURCE_REVIEW.kessler
  if (key === 'mini-ipip-20' || key.startsWith('ipip-')) return SOURCE_REVIEW.ipip
  if (key === 'tipi-10') return SOURCE_REVIEW.tipi
  if (key === 'erq') return SOURCE_REVIEW.erq
  if (key.startsWith('cdc-')) return SOURCE_REVIEW.cdc
  if (key === 'rses-10') return SOURCE_REVIEW.rses
  if (key === 'mspss') return SOURCE_REVIEW.mspss
  if (key === 'brcs') return SOURCE_REVIEW.brcs
  if (key === 'ces-d-20') return SOURCE_REVIEW.cesd
  return { status: 'existing-instrument-specific-guidance', scope: 'Preserved existing guarded instrument-specific explanation; see instrument source audit.' }
}


// Direction explains the named construct, never a population rank or a target.
