function exactDefinition(result, dimension) {
  if (!result?.definitionVersion || !result?.instrumentLocale) return null
  let def
  try { validateProvenance(result); def = getAssessmentDefinition(result.definitionKey, result.definitionVersion, result.instrumentLocale) } catch { return null }
  // A known name is insufficient when provenance or scale shape changed.
  if (result.contentHash !== def.contentHash || result.translationVersion !== def.translationVersion) return null
  const configured = def.scoring?.dimensions?.find(s => s.key === dimension.key)
  const raw = def.questions.find(q => q.id === dimension.key)
  const factor = def.factors?.find(f => 'trait.' + f.key === dimension.key)
  const spec = configured || raw || factor
  if (!spec || spec.min !== dimension.min || spec.max !== dimension.max) return null
  if (!Number.isFinite(dimension.value) || dimension.value < spec.min || dimension.value > spec.max) return null
  return { def, spec, raw: Boolean(raw && !configured), factor: Boolean(factor && !configured) }
}

function mechanics({def, spec, raw, factor}, dimension, lang) {
  const ru = lang === 'ru'
  const value = fmt(dimension.value, lang)
  const count = raw ? 1 : factor ? 4 : spec.items.length
  const reverse = factor ? def.questions.filter(q => q.factor === spec.key && q.keyed === '-').length : spec.reverseItems?.length || 0
  const method = raw ? 'value' : factor ? 'sum' : spec.method
  const mean = method === 'mean'
  let calculation = ru
    ? method === 'value' ? `Это прямой ответ: ${value}.` : method === 'healthy_days' ? `Вычисление: 30 минус индекс неблагополучных дней = ${value}.`
      : method === 'capped_sum' ? `Сумма двух ответов о днях ограничена 30: результат ${value}.`
      : `${mean ? 'Среднее' : 'Сумма'} по ${count} пунктам: ${value}.`
    : method === 'value' ? `This is the direct response: ${value}.` : method === 'healthy_days' ? `Calculation: 30 minus the unhealthy-days index = ${value}.`
      : method === 'capped_sum' ? `The two day counts are added and capped at 30: result ${value}.`
      : `${mean ? 'Mean' : 'Sum'} across ${count} items: ${value}.`
  if (reverse) calculation += ru ? ` Перед расчётом обратно кодируются ${reverse} пункт(а).` : ` ${reverse} item(s) are reverse-scored before calculation.`
  const multiplier = spec.multiplier || 1
  if (multiplier !== 1) calculation += ru ? ` Ответы 0–4 переводятся в баллы умножением на ${multiplier}.` : ` Responses from 0–4 are converted to points by multiplying by ${multiplier}.`
  calculation += ru ? ` Возможный диапазон: ${spec.min}–${spec.max}.` : ` Possible range: ${spec.min}–${spec.max}.`
  const timeframe = times[def.timeframe]?.[lang]
  if (timeframe) calculation += ru ? ` Период: ${timeframe}.` : ` Time frame: ${timeframe}.`
  return { calculation, count, reverse, method, label: ru ? mean ? 'Средний балл ответов' : method === 'value' ? 'Прямой ответ' : method.includes('days') || method === 'capped_sum' ? 'Индекс дней' : 'Суммарный балл ответов' : mean ? 'Mean response score' : method === 'value' ? 'Direct response' : method.includes('days') || method === 'capped_sum' ? 'Day-count index' : 'Summed response score' }
}

function cbiReading(key, value, lang) {
  const ru = lang === 'ru'
  const anchors = ru ? ['никогда / почти никогда', 'редко', 'иногда', 'часто', 'всегда'] : ['never / almost never', 'seldom', 'sometimes', 'often', 'always']
  const low = Math.floor(value / 25), high = Math.ceil(value / 25)
  const point = i => `${i * 25} (${anchors[i]})`
  // Only personal CBI has uniform frequency anchors. Work/client combine
  // degree and frequency, and the final work item is reversed.
  return key === 'cbi-personal'
    ? (ru ? `Средний балл ${fmt(value, lang)} ${low === high ? 'совпадает с числовой опорой ' + point(low) : 'находится между опорами ' + point(low) + ' и ' + point(high)}. ${value === 0 || value === 100 ? 'На этой крайней точке все шесть ответов находятся на соответствующем конце шкалы.' : 'Это среднее по шести ответам, а не утверждение, что каждый ответ был именно таким.'} 0–100 здесь не процент выгорания. В первоисточнике этих правил нет клинических границ «лёгкое / среднее / тяжёлое» для отдельного человека.`
      : `The mean of ${fmt(value, lang)} ${low === high ? 'matches the response point ' + point(low) : 'lies between response points ' + point(low) + ' and ' + point(high)}. ${value === 0 || value === 100 ? 'At this endpoint, all six scored responses are at that endpoint.' : 'This averages six answers; it does not say every answer had that frequency.'} The 0–100 scale is not a percentage of burnout. This original scoring sheet does not provide individual clinical mild/moderate/severe cutoffs.`)
    : (ru ? `Шкала использует опоры 0, 25, 50, 75 и 100. Вопросы о степени и о частоте объединяются в среднее, поэтому ${fmt(value, lang)} нельзя переводить в одну частоту или процент выгорания.${key === 'cbi-work' ? ' Последний пункт о силах для семьи и друзей оценивается обратно: больше сил означает меньше баллов истощения.' : ''} Клиническая категория по этому среднему не назначается.`
      : `The response points are 0, 25, 50, 75 and 100. Degree and frequency questions are averaged together, so ${fmt(value, lang)} cannot be translated into one frequency or a percentage of burnout.${key === 'cbi-work' ? ' The final item about energy for family and friends is reversed: more remaining energy means fewer exhaustion points.' : ''} No clinical category is assigned from this mean.`)
}

function responseScale({def, spec, raw, factor}, lang) {
  const ru = lang === 'ru'
  const questions = raw ? [spec] : factor ? def.questions.filter(q => q.factor === spec.key) : def.questions.filter(q => spec.items.includes(q.id))
  const variants = new Map()
  for (const q of questions) {
    const labels = q.responseAnchors || q.anchors || def.responseAnchors
    if (!Array.isArray(labels) || !labels.length) continue
    const min = q.min ?? def.answerScale?.min
    const max = q.max ?? def.answerScale?.max
    if (!Number.isFinite(min) || !Number.isFinite(max)) continue
    const multiplier = spec.multiplier || 1
    const anchors = labels.map((label, i) => `${fmt((labels.length === 2 ? i ? max : min : min + i) * multiplier, lang)} = ${label}`).join('; ')
    variants.set(anchors, true)
  }
  if (!variants.size) return null
  return (ru ? 'Опоры ответов в форме: ' : 'Response points in this form: ') + [...variants.keys()].join(' | ') +
    (spec.reverseItems?.length || factor ? (ru ? '. Для обратных пунктов баллы разворачиваются перед объединением.' : '. Reverse-keyed items are recoded before combining.') : '.')
}

const CBI_STEPS = {
  'cbi-personal': [
    pair('For 7 days, separately note physical tiredness, emotional depletion and what you could not manage. Add sleep and recovery context; the total cannot tell which experience contributed most.', 'В течение 7 дней отдельно отмечайте физическую усталость, эмоциональное истощение и непосильные дела. Добавляйте контекст сна и восстановления: общий балл не показывает, что внесло больший вклад.'),
    pair('Choose one demand you can reduce or share and one realistic recovery period. If exhaustion is persistent, worsening or affects daily activities, discuss both physical and psychological contributors with a healthcare professional.', 'Выберите одну нагрузку, которую можно уменьшить или разделить, и реальное время восстановления. Если истощение сохраняется, усиливается или мешает делам, обсудите с врачом физические и психологические факторы.'),
  ],
  'cbi-work': [
    pair('Compare workdays and days away from work: note exhaustion before work, after work and energy left for private life. A difference can inform a discussion, but does not prove the cause.', 'Сравните рабочие и свободные дни: отмечайте истощение до работы, после неё и оставшиеся силы на личную жизнь. Различия полезны для обсуждения, но не доказывают причину.'),
    pair('Identify one workable adjustment to workload, priorities, recovery breaks or availability and, where appropriate, discuss it with a manager or occupational-health professional.', 'Выберите посильную поправку к нагрузке, приоритетам, паузам или доступности и при необходимости обсудите её с руководителем или специалистом по здоровью на работе.'),
  ],
  'cbi-client': [
    pair('Notice which aspects of client-facing work cost energy: emotional demands, difficult encounters, repeated contact or limited recovery. Record patterns without naming or blaming clients.', 'Замечайте, что отнимает силы в клиентской работе: эмоциональные требования, трудные встречи, повторные контакты или недостаток восстановления. Фиксируйте закономерности без имён и обвинений клиентов.'),
    pair('Consider one practical support: supervision, a short buffer between sessions, clearer case limits or shared responsibility. Choose an option that fits your role and discuss persistent exhaustion with an appropriate professional.', 'Рассмотрите одну опору: супервизию, паузу между встречами, более ясные границы случаев или разделение ответственности. Выберите подходящий роли вариант и обсудите стойкое истощение со специалистом.'),
  ],
}

export function resultDimensionExplanation(result, dimension, locale = 'en', providedMeaning = null) {
  const lang = locale === 'ru' ? 'ru' : 'en'
  const ru = lang === 'ru'
  const exact = exactDefinition(result, dimension)
  if (!exact) return null
  const { def } = exact
  const baseConstruct = providedMeaning || DIMENSION_MEANINGS[dimension.key]?.[lang]
  const construct = baseConstruct ? [baseConstruct, SCORE_DIRECTIONS[dimension.key]?.[lang]].filter(Boolean).join(' ') : null
  // Newer instruments may supply their own guarded source-specific explanation.
  if (!construct) return null
  const details = mechanics(exact, dimension, lang)
  const cbi = ['cbi-personal','cbi-work','cbi-client'].includes(def.key)
  const original = def.key.startsWith('hh-')
  const mixed = MIXED_HH.has(def.key)
  const review = resultExplanationSource(def.key)
  const limitation = mixed
    ? ru ? 'В этой авторской версии пункты о трудностях и о способах справляться усредняются без обратного кодирования. Поэтому итог нельзя однозначно считать выраженностью проблемы; рассматривайте конкретные ответы и контекст.' : 'This original version averages difficulty and coping items without reversal. Its total therefore cannot be read as an unambiguous level of difficulty; consider the particular answers and context.'
    : original
      ? ru ? 'Авторская саморефлексия Holistic House. Независимые нормы и клинические пороги для этой шкалы не установлены.' : 'Original Holistic House self-reflection. Independent norms and clinical cutoffs for this scale have not been established.'
      : ru ? 'Это объяснение зарегистрированной формы. Сравнение с нормой, диагноз или вывод о причине из одного балла не следует.' : 'This explains the registered form. A score alone does not establish a norm comparison, diagnosis or cause.'
  return {
    construct, ...details,
    anchors: responseScale(exact, lang),
    steps: def.key === 'hh-money-pressure' ? [
      ru ? 'Разделите денежные переживания на конкретные предстоящие обязательства и неопределённые опасения. Выберите один вопрос, для которого можно уточнить сумму, дату или условия.' : 'Separate money worries into specific upcoming obligations and uncertain fears. Choose one question where you can clarify an amount, date or condition.',
      ru ? 'Выделите короткое спокойное время для одного посильного действия: собрать сведения, задать вопрос организации или обсудить нужную поддержку с доверенным человеком. Затем запишите, что стало яснее.' : 'Set aside a brief, calm period for one manageable action: collect information, ask the relevant organization a question or discuss needed support with someone you trust. Then note what became clearer.',
    ] : CBI_STEPS[def.key]?.map(step => step[lang]),
    followUp: def.key === 'hh-money-pressure'
      ? ru ? 'Этот опросник не оценивает платёжеспособность. Если ситуация угрожает базовым нуждам, обратитесь за подходящей местной социальной или долговой консультацией; при стойком эмоциональном напряжении можно отдельно обсудить его со специалистом.' : 'This questionnaire does not assess ability to pay. If basic needs are at risk, consider appropriate local social or debt-advice support; persistent emotional distress can be discussed separately with a qualified professional.'
      : null,
    classificationNote: def.key === 'brcs'
      ? ru ? 'Диапазоны ниже приведены на странице измерения Johns Hopkins. Это описательные ориентиры, не клинические пороги или нормы для вашей популяции; страница также описывает контекст адаптации формулировок.' : 'The ranges below are reported on the Johns Hopkins measurement page. They are descriptive references, not clinical cutoffs or norms for your population; the page also describes adapted wording in its context.'
      : null,
    reading: cbi ? cbiReading(def.key, dimension.value, lang) : limitation,
    limitation, mixed,
    sourceReview: review,
    explanationOrigin: original
      ? ru ? 'Пояснение Holistic House по пунктам авторского опросника.' : 'Holistic House explanation of its original questionnaire items.'
      : review.status === 'original-publication-abstract'
        ? ru ? 'Пояснение Holistic House по зарегистрированной форме и описанию авторов; полный авторский текст интерпретации здесь не проверен.' : 'Holistic House explanation from the registered form and authors’ abstract; the full original interpretation text has not been reviewed here.'
        : ru ? 'Изложение Holistic House по исходной форме и правилам авторов; не дословная авторская интерпретация.' : 'Holistic House paraphrase of the original form and scoring guidance, not a verbatim author interpretation.',
    source: cbi ? CBI_SOURCE + (def.key === 'cbi-personal' ? '#page=1' : '#page=2') : review.url || def.source?.scoringUrl || def.source?.url || null,
    sourceTitle: def.source?.title || def.title,
    citation: def.source?.citation || null,
    provenance: `${def.key} / ${def.version} / ${def.instrumentLocale} / ${def.translationVersion}`,
    languageNote: !original && def.instrumentLocale === 'en' && ru
      ? 'Вопросы — английский оригинал. Русское пояснение не является валидированной русской адаптацией опросника.' : null,
    completeness: cbi
      ? ru ? 'Здесь результат сохраняется только при ответах на все пункты. Это более строгое правило сайта: исходная CBI допускает подсчёт при ответах минимум на 3 личных, 4 рабочих или 3 клиентских пункта.' : 'This site saves a score only after every item is answered. That is stricter than the original CBI rule, which permits scoring with at least 3 personal, 4 work or 3 client items answered.'
      : null,
    recommendationNote: ru ? 'Практические предложения Holistic House для самонаблюдения, не авторские назначения по баллу.' : 'Optional Holistic House reflection steps, not the instrument authors’ treatment instructions.',
  }
}
